 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid nonzero line separates two equal-sized panels.
    for c in range(w):
        if all(grid[r][c] != 0 and grid[r][c] == grid[0][c] for r in range(h)):
            if c == w - c - 1:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                return [[2 if left[r][x] != 0 and right[r][x] != 0 else 0
                         for x in range(c)] for r in range(h)]
